CREATE TABLE users (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, cpf CHAR(11) NOT NULL UNIQUE,
 email VARCHAR(254) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL, address VARCHAR(500) NOT NULL,
 password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL,
 confirmed BOOLEAN NOT NULL DEFAULT FALSE, active BOOLEAN NOT NULL DEFAULT TRUE,
 failed_logins INT NOT NULL DEFAULT 0, locked_until TIMESTAMP(6) NULL,
 created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 CONSTRAINT ck_role CHECK(role IN ('CLIENT','BROKER','ADMIN','OWNER'))
) ENGINE=InnoDB;
CREATE TABLE account_tokens (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, purpose VARCHAR(20) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, used BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE properties (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(160) NOT NULL, type VARCHAR(40) NOT NULL, purpose VARCHAR(10) NOT NULL,
 description TEXT NOT NULL, cep CHAR(8) NOT NULL, street VARCHAR(200) NOT NULL, number VARCHAR(20) NOT NULL,
 neighborhood VARCHAR(100) NOT NULL, city VARCHAR(100) NOT NULL, state CHAR(2) NOT NULL,
 sale_price DECIMAL(15,2) NULL, rent_price DECIMAL(15,2) NULL, area DECIMAL(12,2) NOT NULL,
 bedrooms INT NOT NULL, bathrooms INT NOT NULL, parking INT NOT NULL,
 owner_id BIGINT NOT NULL, broker_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING',
 created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(broker_id) REFERENCES users(id),
 CONSTRAINT ck_property_status CHECK(status IN ('PENDING','AVAILABLE','NEGOTIATING','SOLD','RENTED','INACTIVE')),
 CONSTRAINT ck_property_purpose CHECK(purpose IN ('SALE','RENT','BOTH')),
 CONSTRAINT ck_prices CHECK((purpose='SALE' AND sale_price>0) OR (purpose='RENT' AND rent_price>0) OR (purpose='BOTH' AND sale_price>0 AND rent_price>0)),
 CONSTRAINT ck_area CHECK(area>0 AND bedrooms>=0 AND bathrooms>=0 AND parking>=0),
 INDEX idx_catalog(status,purpose,created_at), INDEX idx_location(city,neighborhood), INDEX idx_broker(broker_id)
) ENGINE=InnoDB;
CREATE TABLE property_images (id BIGINT PRIMARY KEY AUTO_INCREMENT,property_id BIGINT NOT NULL,path VARCHAR(100) NOT NULL,thumbnail VARCHAR(100) NOT NULL,position INT NOT NULL,FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE, UNIQUE(property_id,position));
CREATE TABLE availability (id BIGINT PRIMARY KEY AUTO_INCREMENT,broker_id BIGINT NOT NULL,weekday INT NOT NULL,start_hour INT NOT NULL,end_hour INT NOT NULL,FOREIGN KEY(broker_id) REFERENCES users(id), CHECK(weekday BETWEEN 1 AND 7 AND start_hour>=0 AND end_hour<=24 AND start_hour<end_hour));
CREATE TABLE calendar_years (year INT PRIMARY KEY);
CREATE TABLE holidays (day DATE PRIMARY KEY,name VARCHAR(150) NOT NULL);
CREATE TABLE calendar_blocks (id BIGINT PRIMARY KEY AUTO_INCREMENT,broker_id BIGINT NOT NULL,property_id BIGINT NULL,starts_at TIMESTAMP(6) NOT NULL,ends_at TIMESTAMP(6) NOT NULL,reason VARCHAR(200) NOT NULL,FOREIGN KEY(broker_id) REFERENCES users(id),FOREIGN KEY(property_id) REFERENCES properties(id),CHECK(ends_at>starts_at));
CREATE TABLE visits (id BIGINT PRIMARY KEY AUTO_INCREMENT,property_id BIGINT NOT NULL,client_id BIGINT NOT NULL,broker_id BIGINT NOT NULL,starts_at TIMESTAMP(6) NOT NULL,ends_at TIMESTAMP(6) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(property_id) REFERENCES properties(id),FOREIGN KEY(client_id) REFERENCES users(id),FOREIGN KEY(broker_id) REFERENCES users(id),INDEX idx_visit_time(starts_at,ends_at,status),CHECK(status IN ('SCHEDULED','CONFIRMED','COMPLETED','CANCELLED','NO_SHOW')));
CREATE TABLE contacts (id BIGINT PRIMARY KEY AUTO_INCREMENT,property_id BIGINT NOT NULL,broker_id BIGINT NOT NULL,client_id BIGINT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(30) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(property_id) REFERENCES properties(id),FOREIGN KEY(broker_id) REFERENCES users(id),FOREIGN KEY(client_id) REFERENCES users(id));
CREATE TABLE messages (id BIGINT PRIMARY KEY AUTO_INCREMENT,contact_id BIGINT NOT NULL,author_id BIGINT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(contact_id) REFERENCES contacts(id),FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE notifications (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,message VARCHAR(1000) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE outbox (id BIGINT PRIMARY KEY AUTO_INCREMENT,recipient VARCHAR(254) NOT NULL,subject VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,next_attempt TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),last_error VARCHAR(200) NULL,INDEX idx_outbox(status,next_attempt));
CREATE TABLE audit (id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT NULL,action VARCHAR(60) NOT NULL,resource_type VARCHAR(40) NOT NULL,resource_id BIGINT NULL,details TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE search_terms (id BIGINT PRIMARY KEY AUTO_INCREMENT,term VARCHAR(150) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE SPRING_SESSION (PRIMARY_ID CHAR(36) NOT NULL,SESSION_ID CHAR(36) NOT NULL,CREATION_TIME BIGINT NOT NULL,LAST_ACCESS_TIME BIGINT NOT NULL,MAX_INACTIVE_INTERVAL INT NOT NULL,EXPIRY_TIME BIGINT NOT NULL,PRINCIPAL_NAME VARCHAR(100),CONSTRAINT SPRING_SESSION_PK PRIMARY KEY(PRIMARY_ID)) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES(SESSION_PRIMARY_ID CHAR(36) NOT NULL,ATTRIBUTE_NAME VARCHAR(200) NOT NULL,ATTRIBUTE_BYTES BLOB NOT NULL,CONSTRAINT SPRING_SESSION_ATTRIBUTES_PK PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME),CONSTRAINT SPRING_SESSION_ATTRIBUTES_FK FOREIGN KEY(SESSION_PRIMARY_ID) REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;
